-- E0.3 PROPOSAL ONLY. Evidence rows are written by a separate reconciliation principal, never by bot.
CREATE TABLE public.payout_chain_evidence(id bigserial PRIMARY KEY,evidence_id text NOT NULL UNIQUE,debt_kind text NOT NULL CHECK(debt_kind IN('ORDER','REFERRAL')),debt_id bigint NOT NULL,result text NOT NULL CHECK(result IN('CONFIRMED','NOT_STARTED')),txid text,network text,destination text,crypto_amount numeric(30,12),finality integer,observed_at timestamptz NOT NULL,consumed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),CHECK((result='CONFIRMED' AND txid IS NOT NULL AND crypto_amount>0 AND finality>=1) OR (result='NOT_STARTED' AND txid IS NULL)),UNIQUE(debt_kind,debt_id,evidence_id));
CREATE UNIQUE INDEX uq_payout_chain_txid ON public.payout_chain_evidence(txid) WHERE txid IS NOT NULL;
GRANT SELECT(id,evidence_id,debt_kind,debt_id,result,txid,network,destination,crypto_amount,finality,observed_at,consumed_at,created_at),UPDATE(consumed_at) ON public.payout_chain_evidence TO obsidian_exchange_bot_owner;
GRANT SELECT(order_id,state,network,destination,crypto_amount),UPDATE(state,txid,error_code,finished_at,updated_at,claimed_at) ON public.payout_intents TO obsidian_exchange_bot_owner;
GRANT SELECT(id,state,network,destination,crypto_amount),UPDATE(state,txid,error_code,finished_at,updated_at,claimed_at) ON public.referral_payout_intents TO obsidian_exchange_bot_owner;
GRANT INSERT(order_id,actor,action,from_state,to_state,evidence,txid) ON public.payout_intent_audit TO obsidian_exchange_bot_owner;GRANT USAGE ON SEQUENCE public.payout_intent_audit_id_seq TO obsidian_exchange_bot_owner;
GRANT INSERT(intent_id,actor,action,from_state,to_state,evidence,txid) ON public.referral_payout_intent_audit TO obsidian_exchange_bot_owner;GRANT USAGE ON SEQUENCE public.referral_payout_intent_audit_id_seq TO obsidian_exchange_bot_owner;
CREATE OR REPLACE FUNCTION public.bot_b5_confirm_order_evidence(a_order_id bigint,a_evidence_id text) RETURNS boolean LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE p record;e record;old text;BEGIN a_evidence_id=trim(a_evidence_id);IF a_order_id IS NULL OR a_order_id<=0 OR a_evidence_id IS NULL OR length(a_evidence_id)<1 OR length(a_evidence_id)>128 THEN RAISE EXCEPTION 'invalid_chain_evidence';END IF;SELECT state,network,destination,crypto_amount INTO p FROM public.payout_intents WHERE order_id=a_order_id FOR UPDATE;IF NOT FOUND OR p.state NOT IN('processing','review') THEN RETURN false;END IF;SELECT * INTO e FROM public.payout_chain_evidence WHERE evidence_id=a_evidence_id AND debt_kind='ORDER' AND debt_id=a_order_id AND result='CONFIRMED' AND consumed_at IS NULL FOR UPDATE;IF NOT FOUND OR e.network IS DISTINCT FROM p.network OR e.destination<>p.destination OR e.crypto_amount<>p.crypto_amount OR e.observed_at>clock_timestamp() THEN RETURN false;END IF;old=p.state;UPDATE public.payout_chain_evidence SET consumed_at=clock_timestamp() WHERE id=e.id AND consumed_at IS NULL;IF NOT FOUND THEN RETURN false;END IF;UPDATE public.payout_intents SET state='succeeded',txid=e.txid,error_code=NULL,finished_at=clock_timestamp(),updated_at=clock_timestamp() WHERE order_id=a_order_id AND state=old;IF NOT FOUND THEN RAISE EXCEPTION 'intent_transition_lost';END IF;INSERT INTO public.payout_intent_audit(order_id,actor,action,from_state,to_state,evidence,txid) VALUES(a_order_id,'chain-evidence-principal','confirm_txid',old,'succeeded',a_evidence_id,e.txid);RETURN true;END $$;
CREATE OR REPLACE FUNCTION public.bot_b5_confirm_referral_evidence(a_intent_id bigint,a_evidence_id text) RETURNS boolean LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE p record;e record;old text;BEGIN a_evidence_id=trim(a_evidence_id);IF a_intent_id IS NULL OR a_intent_id<=0 OR a_evidence_id IS NULL OR length(a_evidence_id)<1 OR length(a_evidence_id)>128 THEN RAISE EXCEPTION 'invalid_chain_evidence';END IF;SELECT state,network,destination,crypto_amount INTO p FROM public.referral_payout_intents WHERE id=a_intent_id FOR UPDATE;IF NOT FOUND OR p.state NOT IN('processing','review') THEN RETURN false;END IF;SELECT * INTO e FROM public.payout_chain_evidence WHERE evidence_id=a_evidence_id AND debt_kind='REFERRAL' AND debt_id=a_intent_id AND result='CONFIRMED' AND consumed_at IS NULL FOR UPDATE;IF NOT FOUND OR e.network IS DISTINCT FROM p.network OR e.destination<>p.destination OR e.crypto_amount<>p.crypto_amount OR e.observed_at>clock_timestamp() THEN RETURN false;END IF;old=p.state;UPDATE public.payout_chain_evidence SET consumed_at=clock_timestamp() WHERE id=e.id AND consumed_at IS NULL;UPDATE public.referral_payout_intents SET state='succeeded',txid=e.txid,error_code=NULL,finished_at=clock_timestamp(),updated_at=clock_timestamp() WHERE id=a_intent_id AND state=old;IF NOT FOUND THEN RAISE EXCEPTION 'intent_transition_lost';END IF;INSERT INTO public.referral_payout_intent_audit(intent_id,actor,action,from_state,to_state,evidence,txid) VALUES(a_intent_id,'chain-evidence-principal','confirm_txid',old,'succeeded',a_evidence_id,e.txid);RETURN true;END $$;
CREATE OR REPLACE FUNCTION public.bot_b5_requeue_order_not_started(a_order_id bigint,a_evidence_id text) RETURNS boolean LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE eid bigint;BEGIN SELECT id INTO eid FROM public.payout_chain_evidence WHERE evidence_id=a_evidence_id AND debt_kind='ORDER' AND debt_id=a_order_id AND result='NOT_STARTED' AND consumed_at IS NULL AND observed_at<=clock_timestamp() FOR UPDATE;IF NOT FOUND THEN RETURN false;END IF;PERFORM 1 FROM public.payout_intents WHERE order_id=a_order_id AND state='review' FOR UPDATE;IF NOT FOUND THEN RETURN false;END IF;UPDATE public.payout_chain_evidence SET consumed_at=clock_timestamp() WHERE id=eid AND consumed_at IS NULL;UPDATE public.payout_intents SET state='pending',error_code=NULL,txid=NULL,claimed_at=NULL,finished_at=NULL,updated_at=clock_timestamp() WHERE order_id=a_order_id AND state='review';INSERT INTO public.payout_intent_audit(order_id,actor,action,from_state,to_state,evidence) VALUES(a_order_id,'chain-evidence-principal','requeue_not_started','review','pending',a_evidence_id);RETURN true;END $$;
CREATE OR REPLACE FUNCTION public.bot_b5_requeue_referral_not_started(a_intent_id bigint,a_evidence_id text) RETURNS boolean LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE eid bigint;BEGIN SELECT id INTO eid FROM public.payout_chain_evidence WHERE evidence_id=a_evidence_id AND debt_kind='REFERRAL' AND debt_id=a_intent_id AND result='NOT_STARTED' AND consumed_at IS NULL AND observed_at<=clock_timestamp() FOR UPDATE;IF NOT FOUND THEN RETURN false;END IF;PERFORM 1 FROM public.referral_payout_intents WHERE id=a_intent_id AND state='review' FOR UPDATE;IF NOT FOUND THEN RETURN false;END IF;UPDATE public.payout_chain_evidence SET consumed_at=clock_timestamp() WHERE id=eid AND consumed_at IS NULL;UPDATE public.referral_payout_intents SET state='pending',error_code=NULL,txid=NULL,claimed_at=NULL,finished_at=NULL,updated_at=clock_timestamp() WHERE id=a_intent_id AND state='review';INSERT INTO public.referral_payout_intent_audit(intent_id,actor,action,from_state,to_state,evidence) VALUES(a_intent_id,'chain-evidence-principal','requeue_not_started','review','pending',a_evidence_id);RETURN true;END $$;
ALTER FUNCTION public.bot_b5_confirm_order_evidence(bigint,text) OWNER TO obsidian_exchange_bot_owner;ALTER FUNCTION public.bot_b5_confirm_referral_evidence(bigint,text) OWNER TO obsidian_exchange_bot_owner;ALTER FUNCTION public.bot_b5_requeue_order_not_started(bigint,text) OWNER TO obsidian_exchange_bot_owner;ALTER FUNCTION public.bot_b5_requeue_referral_not_started(bigint,text) OWNER TO obsidian_exchange_bot_owner;
REVOKE ALL ON FUNCTION public.bot_b5_confirm_order_evidence(bigint,text),public.bot_b5_confirm_referral_evidence(bigint,text),public.bot_b5_requeue_order_not_started(bigint,text),public.bot_b5_requeue_referral_not_started(bigint,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.bot_b5_confirm_order_evidence(bigint,text),public.bot_b5_confirm_referral_evidence(bigint,text),public.bot_b5_requeue_order_not_started(bigint,text),public.bot_b5_requeue_referral_not_started(bigint,text) TO obsidian_exchange_bot;
